from collections import defaultdict

def count_components(n, edges):
    g = defaultdict(list)
    for a, b in edges:
        g[a].append(b)
        g[b].append(a)
    seen = set()
    def dfs(u):
        seen.add(u)
        for v in g[u]:
            if v not in seen:
                dfs(v)
    count = 0
    for i in range(n):
        if i not in seen:
            dfs(i)
            count += 1
    return count
